namespace ProjectTower.player;

public class LevelMgr
{
	public static long[] saltToLevel;

	public const int MAX_LEVEL = 550;

	public const int START_SALT_TO_LEVEL = 500;

	public static void Init()
	{
		saltToLevel = new long[550];
		saltToLevel[1] = 500L;
		for (int i = 2; i < saltToLevel.Length; i++)
		{
			saltToLevel[i] = saltToLevel[i - 1] + (i * 5 + 21);
		}
		for (int j = 1; j < saltToLevel.Length; j++)
		{
			saltToLevel[j] = saltToLevel[j] / 20 * 20;
		}
	}

	internal static int GetLevelSaltDifference(int level, int nextLevel)
	{
		if (nextLevel <= level)
		{
			return 0;
		}
		long num = 0L;
		for (int i = level; i < nextLevel; i++)
		{
			num += saltToLevel[i];
		}
		return (int)num;
	}
}
